def backfill_partnerships(apps, schema_editor):
    """stock-partnership §10.2: существующие пары — ACTIVE, activated_at=created_at, заявка, событие ACTIVATED."""
    Partnership = apps.get_model("warehouse", "CompanyStockPartnership")
    Request = apps.get_model("warehouse", "CompanyStockPartnershipRequest")
    Event = apps.get_model("warehouse", "CompanyStockPartnershipEvent")
    for p in Partnership.objects.all():
        req = (
            Request.objects.filter(status="ACCEPTED")
            .filter(
                (Q(from_company_id=p.company_a_id, to_company_id=p.company_b_id))
                | (Q(from_company_id=p.company_b_id, to_company_id=p.company_a_id))
            )
            .order_by("-decided_at")
            .first()
        )
        p.status = "ACTIVE"
        p.activated_at = p.created_at
        p.created_from_request_id = req.id if req else None
        p.save(update_fields=["status", "activated_at", "created_from_request"])
        ev = Event.objects.create(
            partnership_id=p.id, kind="ACTIVATED",
            company_id=req.to_company_id if req else None,
            user_id=req.decided_by_id if req else None,
            payload={"backfill": True, "request": str(req.id) if req else None},
        )
        Event.objects.filter(pk=ev.pk).update(created_at=p.created_at)


